wp:postmeta.wp:meta_value:
.ticker-container {
  width: 100%;
  overflow: hidden;
}

.ticker {
  display: inline-block;
  white-space: nowrap;
  animation: ticker-animation 10s linear infinite;
}

.ticker-item {
  display: inline-block;
  margin-right: 20px;
}

@keyframes ticker-animation {
  0% {
    transform: translateX(0);
  }
  100% {
    transform: translateX(-100%);
  }
}
